import { AbstractControl, ValidationErrors, ValidatorFn } from '@angular/forms';

// 1. Direkt als Prüffunktion
export function digitsOnly(control: AbstractControl): ValidationErrors | null {
  const value = control.value as string;
  if (!value) { return null; }          // leer prüft required
  return /^[0-9]+$/.test(value) ? null : { digitsOnly: { actual: value } };
}

// 2. Mit Parameter: Fabrikfunktion liefert die Prüffunktion
export function exactLength(n: number): ValidatorFn {
  return (control) => !control.value || control.value.length === n
    ? null
    : { exactLength: { required: n, actual: control.value.length } };
}

